{
  "votes": [
    {
      "item": "i01",
      "choice": "v1",
      "reason": "À la page 4, la résolution 2026-04-50 autorise expressément l’enchère et l’acquisition des immeubles identifiés en annexe lors de la vente du 11 juin 2026 : il s’agit d’un acte foncier, et non d’une simple nomination."
    },
    {
      "item": "i02",
      "choice": "v1",
      "reason": "Le point 5.5, à la page 4, atteste l’avis de motion donné par Michel Sanscartier pour le règlement 2009-474-06 modifiant le plan d’urbanisme."
    },
    {
      "item": "i03",
      "choice": "v1",
      "reason": "À la page 5, l’intitulé cité du point 5.6 et la résolution 2026-04-51 attestent l’adoption du projet 2009-474-06 sur le plan d’urbanisme, unité distincte de l’avis de motion."
    },
    {
      "item": "i04",
      "choice": "v1",
      "reason": "Le point 5.7, à la page 5, contient bien l’avis de motion donné par Michel Sanscartier pour le règlement 2009-475-04 relatif aux permis et certificats."
    },
    {
      "item": "i05",
      "choice": "v1",
      "reason": "À la page 6, la résolution 2026-04-52 adopte explicitement le projet de règlement 2009-475-04 modifiant le règlement sur les permis et certificats 2009-475."
    },
    {
      "item": "i06",
      "choice": "v1",
      "reason": "Le point 5.9, à la page 6, atteste l’avis de motion donné par Michel Sanscartier pour le règlement 2009-476-14 modifiant le règlement de zonage 2009-476."
    },
    {
      "item": "i07",
      "choice": "v1",
      "reason": "À la page 7, la résolution 2026-04-53 adopte explicitement le projet de règlement 2009-476-14 modifiant le zonage, ce qui confirme l’étape projet_reglement plutôt qu’une adoption définitive."
    }
  ]
}
